import base64,json,pathlib,tempfile,subprocess,sys
files=json.loads(base64.b64decode(''))
commands=[('./setup36.ps1', 0), ('./setup36.ps1', 1), ('cmd /d /c "dir /b sample" | Out-File -LiteralPath sample\\listing.txt -Encoding utf8 -NoClobber', 0), ('Get-Content -LiteralPath sample\\listing.txt -Encoding utf8', 0), ("'replacement' | Out-File -LiteralPath sample\\listing.txt -Encoding utf8 -NoClobber", 1), ('cmd /d /c "type sample\\missing.txt" | Out-File -LiteralPath sample\\stdout-only.txt -Encoding utf8 -NoClobber; "Native exit: $LASTEXITCODE"', 0), ('(Get-Item -LiteralPath sample\\stdout-only.txt).Length', 0), ('cmd /d /c "type sample\\missing.txt" 2>&1 | Out-File -LiteralPath sample\\combined.txt -Encoding utf8 -NoClobber; "Native exit: $LASTEXITCODE"', 0), ('Get-Content -LiteralPath sample\\combined.txt -Encoding utf8', 0), ('powershell.exe -NoProfile -Command "\'hello\' | Out-File -LiteralPath sample\\hello51.txt -NoClobber"', 0), ("'hello' | Out-File -LiteralPath sample\\hello7.txt -NoClobber", 0), ("'5.1: ' + [BitConverter]::ToString([IO.File]::ReadAllBytes('sample\\hello51.txt')[0..3]); '7: ' + [BitConverter]::ToString([IO.File]::ReadAllBytes('sample\\hello7.txt')[0..3])", 0), ('Get-Content -LiteralPath sample\\hello51.txt -Encoding Unicode | Out-File -LiteralPath sample/converted.txt -Encoding utf8NoBOM -NoClobber', 0), ("Get-Content -LiteralPath sample/converted.txt -Encoding utf8; [BitConverter]::ToString([IO.File]::ReadAllBytes('sample/converted.txt')[0..3])", 0), ('./test_setup36.ps1', 0)]
with tempfile.TemporaryDirectory(prefix='lesson36-record-') as d:
 root=pathlib.Path(d)
 for name,text in files.items():(root/name).write_text(text,encoding='utf-8')
 for command,expected in commands:
  print('\n### CMD: '+command,flush=True)
  result=subprocess.run(['pwsh','-NoProfile','-Command',"$ErrorActionPreference='Stop'; $PSStyle.OutputRendering='PlainText'; "+command],cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace')
  print(result.stdout,end='',flush=True);print('### EXIT: '+str(result.returncode),flush=True)
  if result.returncode!=expected:raise SystemExit('Unexpected exit')
